import { LayaGL } from "../../../../layagl/LayaGL";
import { StatisticsElement } from "../../../../layagl/StatisticsContext";
import { UniformBufferManager } from "../../../DriverDesign/RenderDevice/UniformBufferManager/UniformBufferManager";
import { WebGPURenderEngine } from "../WebGPURenderEngine";
export class WebGPUBufferManager extends UniformBufferManager {
    constructor(engine, useBigBuffer) {
        super(useBigBuffer);
        engine.on("endFrame", this, this.endFrame);
        engine.on("startFrame", this, this.startFrame);
    }
    destroy() {
        return false;
    }
    createGPUBuffer(size, name) {
        return WebGPURenderEngine._instance.getDevice().createBuffer({
            label: name,
            size,
            usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
        });
    }
    writeBuffer(buffer, data, offset, size) {
        WebGPURenderEngine._instance.getDevice().queue.writeBuffer(buffer, offset, data, offset, size);
        LayaGL.statAgent.recordCTData(StatisticsElement.CT_UBOBufferUploadCount, 1);
        LayaGL.statAgent.recordCTData(StatisticsElement.CT_UBOBufferUploadMemory, size / 1048576);
        LayaGL.statAgent.recordCTData(StatisticsElement.CT_BufferUploadCount, 1);
    }
    statisGPUMemory(bytes) {
        super.statisGPUMemory(bytes);
    }
}
